{
  "base": {
    "color": {
      "blue": {
        "600": {
          "$value": "#0066ff",
          "$type": "color"
        }
      },
      "ink": {
        "$value": "#1c1b1a",
        "$type": "color",
        "$description": "Body text"
      },
      "accent": {
        "$value": "{color.blue.600}",
        "$type": "color"
      },
      "veil": {
        "$value": "rgba(15, 18, 23, 0.4)",
        "$type": "color"
      },
      "soft": {
        "$value": "#c6e1ff",
        "$type": "color"
      }
    },
    "space": {
      "2": {
        "$value": "8px",
        "$type": "spacing"
      },
      "4": {
        "$value": "16px",
        "$type": "spacing"
      },
      "gutter": {
        "$value": "{space.4}",
        "$type": "spacing"
      }
    },
    "radius": {
      "md": {
        "$value": "6px",
        "$type": "borderRadius"
      }
    },
    "border": {
      "width": {
        "$value": "1px",
        "$type": "borderWidth"
      }
    },
    "size": {
      "control": {
        "$value": "40px",
        "$type": "sizing"
      }
    },
    "font": {
      "family": {
        "body": {
          "$value": "Inter, Segoe UI, sans-serif",
          "$type": "fontFamilies"
        }
      },
      "size": {
        "md": {
          "$value": "16px",
          "$type": "fontSizes"
        },
        "lg": {
          "$value": "1.25rem",
          "$type": "dimension"
        }
      },
      "weight": {
        "regular": {
          "$value": "400",
          "$type": "fontWeights"
        },
        "bold": {
          "$value": "700",
          "$type": "fontWeights"
        }
      },
      "leading": {
        "body": {
          "$value": "1.5",
          "$type": "number"
        }
      },
      "tracking": {
        "tight": {
          "$value": "-0.02em",
          "$type": "dimension"
        }
      },
      "eyebrow": {
        "case": {
          "$value": "uppercase",
          "$type": "textCase"
        }
      }
    },
    "type": {
      "body": {
        "$value": {
          "fontFamilies": "{font.family.body}",
          "fontSizes": "{font.size.md}",
          "fontWeights": "{font.weight.regular}",
          "letterSpacing": "0px",
          "lineHeights": "{font.leading.body}"
        },
        "$type": "typography"
      }
    },
    "shadow": {
      "sm": {
        "$value": [
          {
            "color": "rgba(15, 18, 23, 0.06)",
            "offsetX": "0",
            "offsetY": "1",
            "blur": "2",
            "spread": "0",
            "inset": false
          }
        ],
        "$type": "shadow"
      },
      "inner": {
        "$value": {
          "color": "{color.ink}",
          "offsetX": "0",
          "offsetY": "1",
          "blur": "0",
          "spread": "0",
          "inset": true
        },
        "$type": "shadow"
      }
    },
    "duration": {
      "fast": {
        "$value": "120",
        "$type": "number"
      }
    }
  },
  "themes/dark": {
    "color": {
      "ink": {
        "$value": "#f0f0f2",
        "$type": "color"
      },
      "accent": {
        "$value": "{color.blue.600}",
        "$type": "color"
      }
    },
    "shadow": {
      "sm": {
        "$value": [
          {
            "color": "rgba(0, 0, 0, 0.5)",
            "offsetX": "0",
            "offsetY": "2",
            "blur": "4",
            "spread": "0",
            "inset": false
          }
        ],
        "$type": "shadow"
      }
    }
  },
  "$themes": [
    {
      "name": "default",
      "group": "dfw",
      "description": "dfw base tokens (design/tokens/tokens.json)",
      "isSource": false,
      "selectedTokenSets": {
        "base": "enabled"
      }
    },
    {
      "name": "dark",
      "group": "dfw",
      "description": "dfw theme design/tokens/themes/dark.json over the base",
      "isSource": false,
      "selectedTokenSets": {
        "base": "enabled",
        "themes/dark": "enabled"
      }
    }
  ],
  "$metadata": {
    "tokenSetOrder": [
      "base",
      "themes/dark"
    ],
    "activeThemes": [
      "dfw/default"
    ],
    "activeSets": [
      "base"
    ]
  }
}

